import json
import httpx
from fastmcp import FastMCP


def create_mcp_server_from_openapi(spec: dict, client: httpx.AsyncClient) -> FastMCP:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 specification as a Python dict
        client: httpx.AsyncClient configured with API base URL

    Returns:
        FastMCP server instance with tools for each API operation
    """
    mcp = FastMCP("openapi-server")

    paths = spec.get("paths", {})

    for path, methods in paths.items():
        for method_name, operation in methods.items():
            if method_name.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method_name}_{path.replace('/', '_')}")
            summary = operation.get("summary", "")
            description = operation.get("description", "")
            full_description = f"{summary}\n{description}".strip() if summary or description else f"{method_name.upper()} {path}"

            parameters = {p.get("name"): p for p in operation.get("parameters", [])}
            request_body = operation.get("requestBody")

            def create_tool_fn(method, endpoint, params_dict, body_spec, op_id):
                async def api_tool(**kwargs) -> str:
                    query_params = {}
                    path_params = {}
                    body_data = None

                    for key, val in kwargs.items():
                        if key == "body":
                            body_data = val
                        elif key in params_dict:
                            param_obj = params_dict[key]
                            if param_obj.get("in") == "path":
                                path_params[key] = val
                            elif param_obj.get("in") == "query":
                                query_params[key] = val
                            else:
                                query_params[key] = val
                        else:
                            if f"{{{key}}}" in endpoint:
                                path_params[key] = val
                            else:
                                query_params[key] = val

                    url = endpoint
                    for key, val in path_params.items():
                        url = url.replace(f"{{{key}}}", str(val))

                    try:
                        resp = await client.request(
                            method=method.upper(),
                            url=url,
                            params=query_params if query_params else None,
                            json=body_data
                        )
                        resp.raise_for_status()
                        return json.dumps(resp.json())
                    except Exception as e:
                        return json.dumps({"error": str(e)})

                api_tool.__name__ = op_id
                return api_tool

            tool_fn = create_tool_fn(method_name, path, parameters, request_body, operation_id)
            mcp.tool(description=full_description)(tool_fn)

    return mcp

